<?php

declare(strict_types = 1);

namespace Modules\Blog\Interfaces\HTTP\Actions;

use Modules\Core\Infrastructure\Http\Request;
use Modules\Core\Infrastructure\Http\Response;
use Modules\Core\Infrastructure\Paths\AppPaths;
use Modules\Core\Interfaces\HTTP\Attributes\Route;
use Modules\Core\Interfaces\HTTP\ErrorPageRenderer;

/**
 * ServeBlogImageAction — read-only serving of generated blog preview images
 * at /storage/blog-images/{path*}.
 *
 * Serves SVG files generated by `bin/cms generate-images`. Security guards:
 * - Only .svg files allowed (extension whitelist)
 * - No dotfile basenames
 * - No `..` segments
 * - Realpath containment inside storage/blog-images
 * - Content-Type is always image/svg+xml (files are never executed)
 */
#[Route(path: '/storage/blog-images/{path*}', method: 'GET', name: 'storage.blog-images')]
final class ServeBlogImageAction
{
    public function handle(Request $request): Response
    {
        $relative = (string) ($request->routeParam('path') ?? '');

        if (!$this->isSafePath($relative)) {
            return $this->notFound();
        }

        $full = AppPaths::instance()->storage('blog-images' . DIRECTORY_SEPARATOR . $relative);
        $real = realpath($full);
        $base = realpath(AppPaths::instance()->storage('blog-images'));

        // Defense-in-depth: lexical checks + realpath containment
        if (false === $real || false === $base
            || !is_file($real)
            || !str_starts_with($real, $base . DIRECTORY_SEPARATOR)
        ) {
            return $this->notFound();
        }

        // Only serve SVG files
        if ('.svg' !== strtolower(substr($real, -4))) {
            return $this->notFound();
        }

        $body = file_get_contents($real);
        if (!is_string($body)) {
            return $this->notFound();
        }

        $response = new Response($body);
        $response->setHeader('Content-Type', 'image/svg+xml');
        $response->setHeader('Cache-Control', 'public, max-age=31536000, immutable');

        return $response;
    }

    /**
     * Lexical path guard — no empty path, null bytes or `..` segments,
     * and the basename must not be a dotfile.
     */
    private function isSafePath(string $relative): bool
    {
        if ('' === $relative || str_contains($relative, "\0") || str_contains($relative, '..')) {
            return false;
        }

        $name = basename($relative);

        return '' !== $name && !str_starts_with($name, '.');
    }

    /**
     * Styled 404 — shared ErrorPageRenderer so file-serving rejections look
     * identical to every other 404 in the app (bare HTML fallback when the
     * layout shell cannot render, e.g. SQLite down).
     */
    private function notFound(): Response
    {
        return ErrorPageRenderer::response(404, 'Not Found', 'The requested file could not be found.');
    }
}
